    try {
      this.options.onCatalogLanded?.();
    } catch (error) {
      this.ctx.logger?.warn?.(`[aggregate] \u5E7F\u64AD\u76EE\u5F55\u53D8\u66F4\u5931\u8D25\uFF08\u76EE\u5F55\u5DF2\u843D\u5730\uFF0C\u4E0D\u5F71\u54CD\u53EF\u7528\u6027\uFF09\uFF1A${String(error)}`);
    }
